CREATE OR REPLACE FUNCTION public.add_delivery_note(_job uuid,_note text,_lat double precision,_lng double precision) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.delivery_jobs; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT * INTO j FROM public.delivery_jobs WHERE id=_job FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not found'; END IF; IF NOT coalesce(public.can_write_pharmacy(j.pharmacy_id,ARRAY['manager','pharmacist','cashier','inventory_manager']::public.user_role[]) OR (j.rider_id=auth.uid() AND public.is_active_delivery_rider(j.pharmacy_id,auth.uid()) AND public.pharmacy_has_plan_feature(j.pharmacy_id,'delivery')),false) THEN RAISE EXCEPTION 'You cannot add delivery notes'; END IF; IF coalesce(trim(_note),'')='' OR length(_note)>500 THEN RAISE EXCEPTION 'Write a short update (max 500 characters)'; END IF; PERFORM public.validate_delivery_coordinates(_lat,_lng); INSERT INTO public.delivery_job_events(job_id,status,actor_id,action,previous_status,new_status,lat,lng,note) VALUES(_job,'update',auth.uid(),'note',j.status,j.status,_lat,_lng,trim(_note)); END $$;